package com.rebuild.arabicwallpapers;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.provider.MediaStore;
import android.view.*;
import android.widget.*;
import android.net.Uri;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
    final int burgundy=Color.rgb(107,31,42), cream=Color.rgb(255,248,245), gold=Color.rgb(242,184,75);
    LinearLayout root, bar; FrameLayout content; String section="home"; int selected=1; Set<String> favorites=new HashSet<>();
    @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(burgundy); getWindow().setNavigationBarColor(burgundy); favorites=new HashSet<>(getPreferences(0).getStringSet("favorites",new HashSet<>())); showHome();}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);return t;}
    void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(cream);setContentView(root); TextView header=text("❖  "+title+"  ❖",23,Color.WHITE);header.setTypeface(null,1);header.setBackgroundColor(burgundy);header.setPadding(12,20,12,20);root.addView(header,new LinearLayout.LayoutParams(-1,-2));content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));bar=new LinearLayout(this);bar.setBackgroundColor(Color.WHITE);bar.setElevation(8);root.addView(bar,new LinearLayout.LayoutParams(-1,60));nav("الرئيسية","⌂","home");nav("المفضلة","♡","favorites");nav("حول التطبيق","ⓘ","about");}
    void nav(String label,String icon,String dest){TextView v=text(icon+"\n"+label,12,burgundy);bar.addView(v,new LinearLayout.LayoutParams(0,-1,1));v.setOnClickListener(w->{if(dest.equals("home"))showHome();else if(dest.equals("favorites"))showFavorites();else showAbout();});}
    void showHome(){section="home";base("خلفيات عربية"); LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(1);wrap.setPadding(12,10,12,10);content.addView(wrap);TextView intro=text("خلفيات قرآنية عربية — تعمل دون إنترنت",16,burgundy);wrap.addView(intro); ScrollView scroll=new ScrollView(this);wrap.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setPadding(2,8,2,8);scroll.addView(grid);for(int i=1;i<=30;i++){final int id=i;grid.addView(card(id,false),new GridLayout.LayoutParams());}}
    View card(int id,boolean favOnly){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(6,6,6,10);c.setBackground(bg(Color.WHITE,18));c.setElevation(2);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=getResources().getDisplayMetrics().widthPixels/2-22;p.setMargins(5,6,5,6);c.setLayoutParams(p);ImageView im=new ImageView(this);im.setImageDrawable(bg(burgundy,12));try{im.setImageBitmap(load(id,false));}catch(Exception ignored){}im.setScaleType(ImageView.ScaleType.CENTER_CROP);c.addView(im,new LinearLayout.LayoutParams(-1,130));TextView title=text("آية قرآنية  "+String.format(Locale.US,"%02d",id),14,burgundy);title.setPadding(0,8,0,0);c.addView(title);TextView heart=text(favorites.contains(id+"")?"♥ محفوظة":"♡ إضافة للمفضلة",13,burgundy);c.addView(heart);heart.setOnClickListener(v->{toggleFav(id);heart.setText(favorites.contains(id+"")?"♥ محفوظة":"♡ إضافة للمفضلة");});c.setOnClickListener(v->showDetail(id));return c;}
    Bitmap load(int id,boolean occurrence)throws IOException{String file="wallpapers/"+(occurrence?"quote_occ_":"quote_qur_")+String.format(Locale.US,"%03d",id)+".png";InputStream in=getAssets().open(file);Bitmap b=BitmapFactory.decodeStream(in);in.close();return b;}
    void showDetail(int id){selected=id;section="detail";base("معاينة الخلفية");LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(1);wrap.setPadding(18,18,18,18);content.addView(wrap);ImageView im=new ImageView(this);try{im.setImageBitmap(load(id,true));}catch(Exception e){try{im.setImageBitmap(load(id,false));}catch(Exception ignored){}}im.setBackground(bg(burgundy,16));im.setScaleType(ImageView.ScaleType.FIT_CENTER);wrap.addView(im,new LinearLayout.LayoutParams(-1,0,1));TextView label=text("خلفية قرآنية رقم "+id,18,burgundy);wrap.addView(label);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);wrap.addView(actions);button(actions,"♡ المفضلة",()->{toggleFav(id);new AlertDialog.Builder(this).setMessage(favorites.contains(id+"")?"أضيفت إلى المفضلة":"أزيلت من المفضلة").setPositiveButton("حسناً",null).show();});button(actions,"مشاركة",()->share(id));button(actions,"حفظ الصورة",()->save(id));}
    void button(LinearLayout parent,String label,Runnable r){Button b=new Button(this);b.setText(label);b.setTextColor(Color.WHITE);b.setBackground(bg(burgundy,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(4,8,4,8);parent.addView(b,p);b.setOnClickListener(v->r.run());}
    void toggleFav(int id){if(favorites.contains(id+""))favorites.remove(id+"");else favorites.add(id+"");getPreferences(0).edit().putStringSet("favorites",new HashSet<>(favorites)).apply();}
    void showFavorites(){section="favorites";base("المفضلة");ScrollView s=new ScrollView(this);content.addView(s);GridLayout g=new GridLayout(this);g.setColumnCount(2);s.addView(g);for(int i=1;i<=30;i++)if(favorites.contains(i+""))g.addView(card(i,true));if(favorites.isEmpty()){TextView t=text("لم تضف خلفيات إلى المفضلة بعد",18,burgundy);content.addView(t);}}
    void showAbout(){base("حول التطبيق");TextView t=text("خلفيات عربية\n\nتطبيق مستقل بلا إعلانات.\nتصفح الخلفيات القرآنية واحفظ المفضلة وشارك الصور.\n\nالمحتوى المتوفر حالياً يعمل دون إنترنت.",18,burgundy);t.setPadding(24,24,24,24);content.addView(t);}
    void share(int id){try{Bitmap b=load(id,true);if(Build.VERSION.SDK_INT<29)throw new IOException("مشاركة الصور تتطلب Android 10 أو أحدث في هذه النسخة");android.content.ContentValues v=new android.content.ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"arabic_wallpaper_share_"+id+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ArabicWallpapers");Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("تعذر تجهيز الصورة");try(OutputStream o=getContentResolver().openOutputStream(uri)){if(o==null)throw new IOException("تعذر فتح الصورة");b.compress(Bitmap.CompressFormat.PNG,100,o);}Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("image/png");intent.putExtra(Intent.EXTRA_STREAM,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,"مشاركة الخلفية"));}catch(Exception e){toast("تعذرت المشاركة: "+e.getMessage());}}
    void save(int id){try{Bitmap b=load(id,true);if(Build.VERSION.SDK_INT>=29){android.content.ContentValues v=new android.content.ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"arabic_wallpaper_"+id+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ArabicWallpapers");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException();try(OutputStream o=getContentResolver().openOutputStream(u)){b.compress(Bitmap.CompressFormat.PNG,100,o);}}else{throw new IOException("Android 10+ required for direct save in this build");}toast("تم حفظ الخلفية في الصور");}catch(Exception e){toast("تعذر حفظ الصورة: "+e.getMessage());}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
